#include <iostream>
#include <vector>
#include <set>

using namespace std;

/**
 * Problem: 11266 - Generate random numbers
 * 
 * 解題思路：
 * 1. 模擬「平方取中法」(Middle-Square Method) 生成隨機數。
 * 2. 給定 4 位數 a0。
 * 3. 計算 a_{i+1}：先算 a_i^2，若不足 8 位則補前導零，取中間 4 位（第 3 到第 6 位）。
 * 4. 簡單做法：a_{i+1} = (a_i * a_i / 100) % 10000。
 * 5. 使用 std::set 記錄已生成的數字，直到出現重複為止，統計 set 的大小。
 */

int main() {
    int a0;
    while (cin >> a0 && a0 != 0) {
        set<int> seen;
        int curr = a0;
        while (seen.find(curr) == seen.end()) {
            seen.insert(curr);
            curr = (curr * curr / 100) % 10000;
        }
        cout << seen.size() << endl;
    }
    return 0;
}
